def _make_session(
    session_id: str = "s1",
    persona: str = "TestPersona",
    grade: str = "B",
    composite: float = 0.75,
    resolution: str = "resolved",
    target_control: str = "SV-1",
    difficulty: str = "medium",
    turns: list | None = None,
    evals: list[str] | None = None,
    qra_citations_total: int = 3,
    shadow_delta: dict | None = None,
) -> dict:
    """Build a minimal session dict for testing."""
    if turns is None:
        turns = []
    if evals:
        turns = [
            {"metadata": {"evaluation": e}} for e in evals
        ]
    return {
        "session_id": session_id,
        "persona": persona,
        "grade": {
            "grade": grade,
            "composite": composite,
            "qra_citations_total": qra_citations_total,
        },
        "resolution": resolution,
        "seed_question": {
            "target_control": target_control,
            "difficulty": difficulty,
            "question": f"What is {target_control}?",
        },
        "turns": turns,
        "shadow_delta": shadow_delta or {},
    }


