# ---------------------------------------------------------------------------
# Test 2: classify_issues and get_persona_evals
# ---------------------------------------------------------------------------
class TestClassifyIssues:
    def test_no_issues_for_good_session(self):
        session = _make_session(
            composite=0.90, evals=["satisfactory"], qra_citations_total=5,
        )
        issues = classify_issues(session)
        assert issues == []

    def test_zero_qra_citations(self):
        session = _make_session(qra_citations_total=0)
        issues = classify_issues(session)
        assert "zero_qra_citations" in issues

    def test_over_clarification(self):
        turns = [{"action": "CLARIFY", "metadata": {}}]
        session = _make_session(target_control="SV-42", turns=turns)
        issues = classify_issues(session)
        assert "over_clarification" in issues

    def test_self_grade_regression(self):
        session = _make_session(
            shadow_delta={"first_composite": 0.85, "final_composite": 0.70},
        )
        issues = classify_issues(session)
        assert "self_grade_regression" in issues

    def test_wrong_answer_eval(self):
        session = _make_session(evals=["wrong"])
        issues = classify_issues(session)
        assert "wrong_answer" in issues

    def test_coverage_gap(self):
        session = _make_session(resolution="no_coverage")
        issues = classify_issues(session)
        assert "coverage_gap" in issues

    def test_get_persona_evals_extracts_strings(self):
        session = _make_session(evals=["satisfactory", "wrong", "satisfactory"])
        evals = get_persona_evals(session)
        assert evals == ["satisfactory", "wrong", "satisfactory"]

    def test_get_persona_evals_empty(self):
        session = _make_session(turns=[{"text": "hello"}])
        evals = get_persona_evals(session)
        assert evals == []

    def test_audit_mendacious_overrides(self):
        session = _make_session(evals=["satisfactory"])
        audit = {"verdict": "MENDACIOUS"}
        issues = classify_issues(session, audit_entry=audit)
        assert "audit_mendacious" in issues

    def test_audit_self_grade_mismatch(self):
        session = _make_session(grade="A", evals=["satisfactory"])
        audit = {"verdict": "MENDACIOUS"}
        issues = classify_issues(session, audit_entry=audit)
        assert "audit_self_grade_mismatch" in issues


