class TestClassifyReasoningError:
    def test_default_insufficient_premise(self):
        session = _make_session()
        result = classify_reasoning_error(session)
        assert result == "insufficient_premise"

    def test_lean4_taxonomy_wins(self):
        session = _make_session()
        session["grade"]["lean4_error_taxonomy"] = {
            "fact_hallucination": 3,
            "invalid_deduction": 1,
        }
        result = classify_reasoning_error(session)
        assert result == "fact_hallucination"

    def test_structured_grade_hallucination(self):
        session = _make_session()
        session["grade"]["reasoning_sound"] = False
        session["grade"]["hallucinated_facts"] = True
        result = classify_reasoning_error(session)
        assert result == "fact_hallucination"

    def test_structured_grade_missing_evidence(self):
        session = _make_session()
        session["grade"]["reasoning_sound"] = False
        session["grade"]["missing_evidence"] = True
        result = classify_reasoning_error(session)
        assert result == "information_omission"


# ---------------------------------------------------------------------------
# Test 4: build_diagnosis (integration of classify + rerun)
# ---------------------------------------------------------------------------
class TestBuildDiagnosis:
    def test_empty_sessions(self):
        diag = build_diagnosis([])
        assert diag["summary"]["total"] == 0
        assert diag["sessions"] == []

    def test_single_satisfied_session(self):
        session = _make_session(
            grade="A", composite=0.92, evals=["satisfactory"],
            qra_citations_total=5,
        )
        diag = build_diagnosis([session])
        assert diag["summary"]["total"] == 1
        assert diag["summary"]["satisfied_rate"] == 1.0
        assert len(diag["rerun_candidates"]) == 0

    def test_unsatisfied_low_composite_becomes_rerun_candidate(self):
        session = _make_session(
            grade="C", composite=0.50, evals=["unsatisfactory"],
            resolution="partial",
        )
        diag = build_diagnosis([session])
        assert len(diag["rerun_candidates"]) == 1
        assert diag["rerun_candidates"][0] == "s1"

    def test_systemic_detection(self):
        # 3 sessions all with zero QRA = systemic (>50%)
        sessions = [
            _make_session(session_id=f"s{i}", qra_citations_total=0)
            for i in range(3)
        ]
        diag = build_diagnosis(sessions)
        systemic_issues = [
            si for si in diag["systemic_issues"] if si["is_systemic"]
        ]
        systemic_names = {si["issue"] for si in systemic_issues}
        assert "zero_qra_citations" in systemic_names

    def test_turn_stats_present(self):
        session = _make_session(evals=["satisfactory"])
        diag = build_diagnosis([session])
        assert "turn_stats" in diag
        assert "avg_turns_satisfied" in diag["turn_stats"]


