# Test 5: converge_helpers pure functions
# ---------------------------------------------------------------------------
class TestConvergeHelpers:
    def test_compare_improved(self):
        orig = [_make_session(session_id="s1", composite=0.50)]
        new = [_make_session(session_id="s1", composite=0.90)]
        improved, regressed = compare_sessions(orig, new)
        assert improved == 1
        assert regressed == 0

    def test_compare_regressed(self):
        orig = [_make_session(session_id="s1", composite=0.90)]
        new = [_make_session(session_id="s1", composite=0.40)]
        improved, regressed = compare_sessions(orig, new)
        assert improved == 0
        assert regressed == 1

    def test_compare_no_change(self):
        orig = [_make_session(session_id="s1", composite=0.75)]
        new = [_make_session(session_id="s1", composite=0.76)]
        improved, regressed = compare_sessions(orig, new)
        assert improved == 0
        assert regressed == 0

    def test_merge_keeps_better(self):
        orig = [_make_session(session_id="s1", composite=0.50)]
        new = [_make_session(session_id="s1", composite=0.90)]
        merged = merge_sessions(orig, new)
        assert len(merged) == 1
        assert merged[0]["grade"]["composite"] == 0.90

    def test_merge_keeps_original_on_regression(self):
        orig = [_make_session(session_id="s1", composite=0.90)]
        new = [_make_session(session_id="s1", composite=0.40)]
        merged = merge_sessions(orig, new)
        assert merged[0]["grade"]["composite"] == 0.90


