class TestChartData:
    def test_heatmap_groups_by_difficulty(self):
        sessions = [
            _make_session(difficulty="easy", grade="A"),
            _make_session(difficulty="hard", grade="F"),
            _make_session(difficulty="easy", grade="B"),
        ]
        hm = _build_heatmap(sessions)
        assert "easy" in hm
        assert "hard" in hm
        assert hm["easy"]["A"] == 1
        assert hm["easy"]["B"] == 1
        assert hm["hard"]["F"] == 1

    def test_grade_dist_from_diagnosis(self):
        diag = {"summary": {"grades": {"A": 5, "B": 3, "F": 1}}}
        result = _build_grade_dist(diag)
        assert result["metrics"]["A"] == 5

    def test_issue_dist_from_diagnosis(self):
        diag = {"systemic_issues": [
            {"issue": "zero_qra_citations", "count": 10},
            {"issue": "coverage_gap", "count": 2},
        ]}
        result = _build_issue_dist(diag)
        assert result["metrics"]["zero_qra_citations"] == 10

    def test_radar_extracts_dimensions(self):
        session = _make_session()
        session["grade"]["scores"] = {
            dim: 0.8 + i * 0.01 for i, dim in enumerate(RUBRIC_DIMENSIONS)
        }
        result = _build_radar([session])
        assert len(result["series"]) == 1
        label = list(result["series"].keys())[0]
        assert "accuracy" in result["series"][label]
